defmodule ExSdr.Test.GnuRadioFixture do
  @moduledoc false
  # Shared DSP cases (test/dsp_cases/*.json) and the GNU Radio output for
  # them (test/fixtures/gnuradio/<case>/, regenerated by
  # scripts/gnuradio_golden.sh).

  alias NxFixed, as: DSP

  @cases_dir Path.expand("../dsp_cases", __DIR__)
  @fixtures_dir Path.expand("../fixtures/gnuradio", __DIR__)

  def cases_dir, do: @cases_dir
  def fixtures_dir, do: @fixtures_dir

  def case_paths, do: @cases_dir |> Path.join("*.json") |> Path.wildcard() |> Enum.sort()

  def read_case(path), do: path |> File.read!() |> JSON.decode!()

  @doc """
  Loads the GNU Radio data for `case` from `root`. Fails if it was generated
  from a different version of the case file.
  """
  def load(case, case_path, root \\ @fixtures_dir) do
    dir = Path.join(root, case["name"])
    manifest = dir |> Path.join("manifest.json") |> File.read!() |> JSON.decode!()
    sha = :crypto.hash(:sha256, File.read!(case_path)) |> Base.encode16(case: :lower)

    if manifest["case_sha256"] != sha do
      raise "GNU Radio data for #{case["name"]} is stale (case file changed): run scripts/gnuradio_golden.sh"
    end

    inputs =
      for {spec, i} <- Enum.with_index(input_specs(case)) do
        name = "input" <> if(i == 0, do: "", else: Integer.to_string(i))

        items =
          if spec["type"] == "bytes",
            do: :binary.bin_to_list(File.read!(Path.join(dir, name <> ".u8"))),
            else:
              for(<<v::little-signed-16 <- File.read!(Path.join(dir, name <> ".s16le"))>>, do: v)

        if spec["type"] == "complex", do: pairs(items), else: items
      end

    references =
      for {spec, j} <- Enum.with_index(output_specs(case)) do
        name = "gnuradio" <> if(j == 0, do: "", else: Integer.to_string(j))
        values = read_reference(Path.join(dir, name), spec["type"])
        if spec["type"] == "complex", do: pairs(values), else: values
      end

    %{
      manifest: manifest,
      # one input: its items; several: one list of the inputs' items per sample
      input: if(length(inputs) == 1, do: hd(inputs), else: Enum.zip_with(inputs, & &1)),
      inputs: inputs,
      reference: List.first(references),
      references: references
    }
  end

  defp read_reference(base, "bytes"), do: :binary.bin_to_list(File.read!(base <> ".u8"))

  defp read_reference(base, "short"),
    do: for(<<v::little-signed-16 <- File.read!(base <> ".s16le")>>, do: v)

  defp read_reference(base, "int"),
    do: for(<<v::little-signed-32 <- File.read!(base <> ".s32le")>>, do: v)

  defp read_reference(base, _type),
    do: for(<<v::little-float-32 <- File.read!(base <> ".f32le")>>, do: v)

  @doc """
  Loads every case of `family` (cases in test/dsp_cases/<family>/,
  GNU Radio data in test/fixtures/gnuradio/<family>/, generated by
  `scripts/gnuradio_golden.sh test/fixtures/gnuradio/<family> test/dsp_cases/<family>`):
  `[{case, data}]`.
  """
  def family(family) do
    for path <- Path.wildcard(Path.join([@cases_dir, family, "*.json"])) |> Enum.sort() do
      case = read_case(path)
      {case, load(case, path, Path.join(@fixtures_dir, family))}
    end
  end

  # "inputs" (several) or "input" (one); "outputs" or "output" (default: the input's type).
  defp input_specs(case), do: case["inputs"] || [case["input"]]

  defp output_specs(case),
    do: case["outputs"] || [case["output"] || %{"type" => hd(input_specs(case))["type"]}]

  defp pairs(list), do: list |> Enum.chunk_every(2) |> Enum.map(&List.to_tuple/1)

  @doc "The `NxFixed.Num` format described by a case's `format` map."
  def format(%{"bits" => bits, "frac" => frac} = f),
    do:
      NxFixed.Num.q(bits, frac,
        rounding: String.to_atom(f["rounding"]),
        lut_bits: f["lut_bits"] || 10
      )

  def format("float"), do: NxFixed.Num.float()

  @doc """
  Runs the case's `ExSdr.DSP.Blocks` block over `input` (Q15 integers) in
  `format`; returns Elixir floats (1.0 = full scale), `{re, im}` for complex.
  """
  def run_block(case, input, format, implementation \\ :nx)

  def run_block(case, input, %NxFixed.Num.Format{} = format, implementation) do
    %{"block" => block, "params" => params} = case
    args = Enum.map(block["args"] || [], &arg(&1, params, format))
    opts = Enum.map(block["opts"] || %{}, fn {k, v} -> {String.to_atom(k), value(v, params)} end)
    fun = Function.capture(ExSdr.DSP.Blocks, String.to_atom(block["name"]), 3 + length(args))

    # All samples at once through the compiled loop (EXLA when available).
    samples =
      if hd(input_specs(case))["type"] == "complex" do
        {re, im} = Enum.unzip(input)
        {samples(re, format), samples(im, format)}
      else
        samples(input, format)
      end

    state = state(block["state"], params, format)
    kernel_opts = [format: format] ++ opts

    case implementation do
      :nx ->
        {outputs, _state} =
          DSP.run_scan_stacked(fun, samples, state, args, kernel_opts: kernel_opts)

        to_floats(outputs)

      # ExSdr.CPU: SIMD kernels where available; returns which one ran.
      :cpu ->
        {outputs, _state, impl} = ExSdr.CPU.run_block(fun, samples, state, args, kernel_opts)
        {to_floats(outputs), impl}
    end
  end

  defp to_floats(outputs) do
    case NxFixed.Num.to_float(outputs) do
      {re, im} -> Enum.zip(re, im)
      values -> values
    end
  end

  defp samples(ints, format), do: NxFixed.Num.from_int(Nx.tensor(ints, type: :s16), 15, format)

  # Argument and state specs: {"phase": p} is a u16 phase word in every
  # format, {"real": p} a real number in the instance's format.
  defp arg(%{"phase" => p}, params, _format), do: Nx.tensor(value(p, params), type: :u16)
  defp arg(%{"real" => p}, params, format), do: NxFixed.Num.constant(value(p, params), format)

  defp state(%{"zeros" => n, "complex" => true}, _params, format),
    do: {NxFixed.Num.zeros({n}, format), NxFixed.Num.zeros({n}, format)}

  defp state(%{"zeros" => n}, _params, format), do: NxFixed.Num.zeros({n}, format)
  defp state(spec, params, format), do: arg(spec, params, format)

  defp value(name, params) when is_binary(name), do: Map.fetch!(params, name)
  defp value(v, _params), do: v

  @doc "SNR in dB of `signal` against `reference`."
  def snr_db(reference, signal) do
    {power, error} =
      Enum.zip(reference, signal)
      |> Enum.reduce({0.0, 0.0}, fn {r, s}, {p, e} -> {p + mag2(r), e + mag2(sub(s, r))} end)

    # as a difference of logs: the ratio itself overflows for an exact match of large (integer) values
    10 * (:math.log10(power) - :math.log10(max(error, 1.0e-300)))
  end

  @doc "`{max error in Q15 LSB, sample index}`."
  def worst_sample(reference, signal) do
    Enum.zip(reference, signal)
    |> Enum.with_index()
    |> Enum.map(fn {{r, s}, i} -> {:math.sqrt(mag2(sub(s, r))) * 32768, i} end)
    |> Enum.max()
  end

  defp sub({a, b}, {c, d}), do: {a - c, b - d}
  defp sub(a, b), do: a - b
  defp mag2({a, b}), do: a * a + b * b
  defp mag2(a), do: a * a
end
